mapper.select:
SELECT COUNT(*)
FROM news_article
WHERE dedup_hash = #{dedupHash}

SELECT id, stock_code AS stockCode, title, summary, source_name AS sourceName, article_url AS articleUrl,
       published_at AS publishedAt, collected_at AS collectedAt, keyword_score AS keywordScore, ai_score AS aiScore, dedup_hash AS dedupHash
FROM news_article
WHERE stock_code = #{stockCode}
ORDER BY COALESCE(published_at, collected_at) DESC, id DESC
LIMIT #{limit}
